// Build-time font self-hosting for the Lune_X reference template.
// No font CDN requests at runtime. Fonts are fetched from the Google Fonts CSS
// endpoint by GitHub Actions and committed as local WOFF2 assets.
// Font licenses: https://github.com/google/fonts/tree/main/ofl
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
const cssUrl="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,700;12..96,800&family=Instrument+Sans:wght@400;600&display=swap";
const source=await fetch(cssUrl,{headers:{"User-Agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36"}});
if(!source.ok)throw Error("Google Fonts stylesheet fetch failed: "+source.status);
const body=await source.text();
const faces=[...body.matchAll(/@font-face\s*\{([\s\S]*?)\}/g)].map(m=>m[1]);
const selected=faces.filter(face=>/U\+0000-00FF/i.test(face)&&/format\(['"]?woff2['"]?\)/i.test(face));
if(selected.length<4)throw Error("Not all expected Latin WOFF2 font faces were found (found "+selected.length+")");
const dir="assets/fonts";await mkdir(dir,{recursive:true});
const seen=new Map(),rules=[];
for(const face of selected){
 const family=face.match(/font-family:\s*['"]?([^;\n'"]+)/i)?.[1]?.trim();
 const weight=face.match(/font-weight:\s*([^;]+)/i)?.[1]?.trim();
 const url=face.match(/src:\s*url\((https:[^)]+)\)/i)?.[1];
 if(!family||!weight||!url||!["Bricolage Grotesque","Instrument Sans"].includes(family))continue;
 const key=family+"-"+weight;if(seen.has(key))continue;
 const file=family==="Bricolage Grotesque"?"bricolage":"instrument";
 const name=file+"-"+weight.replace(/[^a-z0-9]/gi,"-")+".woff2";
 const response=await fetch(url);if(!response.ok)throw Error("Font download failed "+url);
 const bytes=Buffer.from(await response.arrayBuffer());
 if(bytes.length<3000||bytes.length>500000)throw Error("Unexpected font size "+bytes.length);
 await writeFile(path.join(dir,name),bytes);seen.set(key,name);
 rules.push('@font-face{font-family:"'+family+'";font-style:normal;font-weight:'+weight+';font-display:swap;src:url("../fonts/'+name+'") format("woff2")}');
}
if(![...seen.keys()].some(k=>k.startsWith("Bricolage Grotesque"))||![...seen.keys()].some(k=>k.startsWith("Instrument Sans")))throw Error("Missing expected font families");
await writeFile("assets/css/brand-fonts.css","/* Self-hosted fonts; generated by GitHub Actions. Do not edit manually. */\n"+rules.join("\n")+"\n");
console.log(JSON.stringify({downloaded:[...seen.values()],faceCount:rules.length}));
